1	import 'package:cerne/core/network/api_client.dart';
2	import 'package:cerne/core/network/failure.dart';
3	import 'package:cerne/features/auth/data/auth_remote_data_source.dart';
4	import 'package:cerne/features/session/domain/entities/session.dart';
5	import 'package:fpdart/fpdart.dart';
6	import 'package:mocktail/mocktail.dart';
7	import 'package:test/test.dart';
8	
9	class MockApiClient extends Mock implements ApiClient {}
10	
11	void main() {
12	  late MockApiClient apiClient;
13	  late AuthRemoteDataSource dataSource;
14	
15	  const email = 'person@example.com';
16	  const password = 'correct-horse';
17	
18	  final validData = {
19	    'session': {
20	      'accessToken': 'access-token',
21	      'refreshToken': 'refresh-token',
22	      'expiresAt': 1234567890,
23	      'tokenType': 'bearer',
24	    },
25	    'user': {'id': 'user-1', 'email': email},
26	  };
27	
28	  setUpAll(() {
29	    registerFallbackValue(AuthMode.anonKey);
30	  });
31	
32	  setUp(() {
33	    apiClient = MockApiClient();
34	    dataSource = AuthRemoteDataSource(apiClient);
35	  });
36	
37	  void stubCall(String function, Either<Failure, Map<String, dynamic>> result) {
38	    when(
39	      () => apiClient.call(
40	        function,
41	        method: any(named: 'method'),
42	        body: any(named: 'body'),
43	        pathSegments: any(named: 'pathSegments'),
44	        authMode: any(named: 'authMode'),
45	      ),
46	    ).thenAnswer((_) async => result);
47	  }
48	
49	  for (final entry in {
50	    'auth-login': (String e, String p) => dataSource.login(email: e, password: p),
51	    'auth-signup': (String e, String p) => dataSource.signUp(email: e, password: p),
52	  }.entries) {
53	    final function = entry.key;
54	    final invoke = entry.value;
55	
56	    group(function, () {
57	      test('calls apiClient.call($function, ...) with AuthMode.anonKey', () async {
58	        stubCall(function, Right(validData));
59	
60	        await invoke(email, password);
61	
62	        verify(
63	          () => apiClient.call(
64	            function,
65	            method: 'POST',
66	            body: {'email': email, 'password': password},
67	            authMode: AuthMode.anonKey,
68	          ),
69	        ).called(1);
70	      });
71	
72	      test('parses a valid success body into Session', () async {
73	        stubCall(function, Right(validData));
74	
75	        final result = await invoke(email, password);
76	
77	        expect(result.isRight(), isTrue);
78	        final session = result.toNullable()!;
79	        expect(session.accessToken, 'access-token');
80	        expect(session.refreshToken, 'refresh-token');
81	        expect(session.expiresAt, 1234567890);
82	        expect(session.tokenType, 'bearer');
83	        expect(session.account.id, 'user-1');
84	        expect(session.account.email, email);
85	      });
86	
87	      test('NetworkTimeoutFailure passes through unchanged', () async {
88	        const failure = NetworkTimeoutFailure(message: 'timed out', requestId: 'r1');
89	        stubCall(function, const Left(failure));
90	
91	        final result = await invoke(email, password);
92	
93	        expect(result, const Left<Failure, Session>(failure));
94	      });
95	
96	      test('NetworkOfflineFailure passes through unchanged', () async {
97	        const failure = NetworkOfflineFailure(message: 'no connection', requestId: 'r2');
98	        stubCall(function, const Left(failure));
99	
100	        final result = await invoke(email, password);
101	
102	        expect(result, const Left<Failure, Session>(failure));
103	      });
104	
105	      test('ValidationFailure passes through unchanged (backend rejects submission)', () async {
106	        const failure = ValidationFailure(message: 'malformed request', requestId: 'r3');
107	        stubCall(function, const Left(failure));
108	
109	        final result = await invoke(email, password);
110	
111	        expect(result, const Left<Failure, Session>(failure));
112	      });
113	
114	      test('a malformed success body (missing session/user) becomes ValidationFailure', () async {
115	        stubCall(function, const Right({'unexpected': true}));
116	
117	        final result = await invoke(email, password);
118	
119	        expect(result.isLeft(), isTrue);
120	        expect(result.getLeft().toNullable(), isA<ValidationFailure>());
121	      });
122	
123	      test('a success body with wrong field types becomes ValidationFailure', () async {
124	        stubCall(function, Right({
125	          'session': {
126	            'accessToken': 123, // wrong type
127	            'refreshToken': 'refresh-token',
128	            'expiresAt': 1234567890,
129	            'tokenType': 'bearer',
130	          },
131	          'user': {'id': 'user-1', 'email': email},
132	        }));
133	
134	        final result = await invoke(email, password);
135	
136	        expect(result.isLeft(), isTrue);
137	        expect(result.getLeft().toNullable(), isA<ValidationFailure>());
138	      });
139	    });
140	  }
141	}
