1	import 'package:cerne/core/network/failure.dart';
2	import 'package:cerne/core/storage/secure_token_storage.dart';
3	import 'package:cerne/features/auth/domain/entities/account.dart';
4	import 'package:cerne/features/session/data/session_remote_data_source.dart';
5	import 'package:cerne/features/session/domain/entities/session.dart';
6	import 'package:cerne/features/session/domain/repositories/session_repository.dart';
7	import 'package:fpdart/fpdart.dart';
8	
9	class SessionRepositoryImpl implements SessionRepository {
10	  const SessionRepositoryImpl({
11	    required this._remoteDataSource,
12	    required this._tokenStorage,
13	  });
14	
15	  final SessionRemoteDataSource _remoteDataSource;
16	  final SecureTokenStorage _tokenStorage;
17	
18	  @override
19	  Future<Either<Failure, Session>> checkSession() async {
20	    final result = await _remoteDataSource.checkSession();
21	    return result.match<Future<Either<Failure, Session>>>(
22	      (failure) => Future.value(Left(failure)),
23	      _assembleFromCheckSession,
24	    );
25	  }
26	
27	  @override
28	  Future<Either<Failure, Session>> refresh() async {
29	    final refreshToken = await _tokenStorage.readRefreshToken();
30	    if (refreshToken == null) {
31	      return const Left(
32	        AuthInvalidFailure(message: 'No refresh token stored', requestId: ''),
33	      );
34	    }
35	
36	    final result = await _remoteDataSource.refresh(refreshToken: refreshToken);
37	    return result.match<Future<Either<Failure, Session>>>(
38	      (failure) => Future.value(Left(failure)),
39	      _assembleFromRefresh,
40	    );
41	  }
42	
43	  @override
44	  Future<void> persist(Session session) {
45	    return _tokenStorage.writeSession(
46	      accessToken: session.accessToken,
47	      refreshToken: session.refreshToken,
48	      expiresAt: session.expiresAt,
49	      tokenType: session.tokenType,
50	    );
51	  }
52	
53	  @override
54	  Future<void> clear() => _tokenStorage.delete();
55	
56	  @override
57	  Future<bool> hasStoredSession() async {
58	    return (await _tokenStorage.readRefreshToken()) != null;
59	  }
60	
61	  Future<Either<Failure, Session>> _assembleFromCheckSession(
62	    Map<String, dynamic> data,
63	  ) async {
64	    try {
65	      final userJson = data['user'] as Map<String, dynamic>;
66	      final expiresAt = data['expiresAt'] as int;
67	
68	      final accessToken = await _tokenStorage.readAccessToken();
69	      final refreshToken = await _tokenStorage.readRefreshToken();
70	      final tokenType = await _tokenStorage.readTokenType();
71	      if (accessToken == null || refreshToken == null || tokenType == null) {
72	        return const Left(
73	          ValidationFailure(message: 'No stored session', requestId: ''),
74	        );
75	      }
76	
77	      return Right(
78	        Session(
79	          accessToken: accessToken,
80	          refreshToken: refreshToken,
81	          expiresAt: expiresAt,
82	          tokenType: tokenType,
83	          account: Account(
84	            id: userJson['id'] as String,
85	            email: userJson['email'] as String,
86	          ),
87	        ),
88	      );
89	    } on TypeError {
90	      return const Left(
91	        ValidationFailure(message: 'Malformed session response', requestId: ''),
92	      );
93	    }
94	  }
95	
96	  // auth-refresh's response carries only new tokens, never a `user` object
